def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    objects = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                rr, cc = stack.pop()
                cells.append((rr, cc))
                for nr, nc in ((rr-1, cc), (rr+1, cc), (rr, cc-1), (rr, cc+1)):
                    if 0 <= nr < h and 0 <= nc < w and (nr, nc) not in seen and grid[nr][nc] == color:
                        seen.add((nr, nc))
                        stack.append((nr, nc))
            objects.append((color, cells))

    # For each color, its upper occurrence goes in the upper output row and
    # its lower occurrence goes in the lower output row.
    by_color = {}
    for obj in objects:
        by_color.setdefault(obj[0], []).append(obj)
    upper, lower = [], []
    for color, pair in by_color.items():
        pair.sort(key=lambda obj: min(r for r, c in obj[1]))
        upper.append(pair[0])
        lower.append(pair[1])

    # The lower occurrences establish the left-to-right color order.
    lower.sort(key=lambda obj: min(c for r, c in obj[1]))
    column = {color: i for i, (color, cells) in enumerate(lower)}
    out = [[0] * w for _ in range(h)]
    for group, baseline in ((upper, 6), (lower, 9)):
        for color, cells in group:
            min_r = min(r for r, c in cells)
            min_c = min(c for r, c in cells)
            x = 3 * column[color]
            y = baseline - (max(r for r, c in cells) - min_r)
            for r, c in cells:
                out[y + r - min_r][x + c - min_c] = color
    return out

